# -*- coding: utf-8 -*-
"""Lecture 42 vignette pool A -- Pulmonary Vascular Disorders: cor pulmonale (definition and causes,
pathophysiology and hemodynamics, diagnosis and management) and pulmonary hypertension classification and
presentation (slides 4-16, 19-23).

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.
EXPLANATIONS follow tools/question_writing/EXPLAIN_DEEP.md: the key names the decisive clue and the slide fact;
each wrong choice says why it fails for THIS patient, the replacing fact, and a "Tell:".

Held per cms_e7l42_scope.py: echocardiography is never called the gold standard; no mean pulmonary artery pressure
threshold is given; wedge pressures in stems are 12 mmHg or less (pre-capillary) or 22 mmHg or more (left heart);
the World Health Organization group items state the deciding finding (wedge pressure, lung studies, perfusion scan)
so one group fits; the s21 symptom percentages and the s22 venous pressure number are never used.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e7l42_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


def ORD(d, asc):
    d["ordered"] = True; d["asc"] = asc; return d


